@import url('https://fonts.googleapis.com/css2?family=DM+Mono:wght@400;500&family=Space+Grotesk:wght@400;500;600;700&display=swap');
:root{--ink:#070b17;--panel:#0b1222;--line:rgba(155,190,228,.16);--cyan:#71f6e2;--blue:#77a9ff;--muted:#75839a;--white:#edf4ff;--pink:#ff7297;--mono:'DM Mono',monospace;--display:'Space Grotesk',sans-serif}*{box-sizing:border-box}html,body{margin:0;width:100%;height:100%;overflow:hidden;background:var(--ink);color:var(--white);font-family:var(--display)}body{min-width:320px}.game-shell{position:relative;width:100vw;height:100dvh;min-height:500px;overflow:hidden;background:radial-gradient(ellipse at 50% 49%,#101a32 0,#080e1d 56%,#060914 100%);isolation:isolate}canvas{position:absolute;inset:0;width:100%;height:100%;display:block}.scanlines{pointer-events:none;position:absolute;inset:0;z-index:2;opacity:.16;background:linear-gradient(transparent 50%,rgba(0,0,0,.2) 50%);background-size:100% 4px;mix-blend-mode:soft-light}.game-shell:after{content:"";position:absolute;inset:0;z-index:2;pointer-events:none;box-shadow:inset 0 0 160px 35px rgba(2,5,14,.68)}.topbar{position:absolute;left:0;right:0;top:0;height:72px;padding:0 clamp(18px,4.4vw,70px);display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid rgba(151,183,224,.08);z-index:4}.brand{display:flex;align-items:center;gap:12px;color:#eaf1ff;text-decoration:none;letter-spacing:.13em;font-weight:700;font-size:12px}.brand-mark{font-size:23px;color:var(--cyan);text-shadow:0 0 16px #71f6e2}.brand-dim{font-weight:400;color:#738097;letter-spacing:.1em}.top-actions{display:flex;align-items:center;gap:12px}.live-tag,.footer,.microcopy,.eyebrow,.stat-label,.score-label,.best-label,.wave-label,.wave-sub,.crosshair-hint,.dash-status,.control-row,.mobile-tip{font-family:var(--mono);letter-spacing:.11em}.live-tag{font-size:9px;color:#9eb2c7;margin-right:8px}.live-tag i,.footer-center i{display:inline-block;width:6px;height:6px;border-radius:50%;background:#76f6d2;box-shadow:0 0 11px #76f6d2;margin-right:7px}.icon-btn{width:34px;height:34px;background:rgba(14,24,43,.72);border:1px solid var(--line);border-radius:8px;color:#aebdd0;font-size:16px;cursor:pointer;transition:.2s}.icon-btn:hover{color:var(--cyan);border-color:#71f6e277}.hud{position:absolute;z-index:3;left:clamp(18px,4.4vw,70px);right:clamp(18px,4.4vw,70px);top:94px;display:grid;grid-template-columns:1fr 1fr 1fr;align-items:start;pointer-events:none}.hud-left{width:min(230px,90%)}.stat-card{margin-bottom:15px}.stat-label{display:flex;justify-content:space-between;color:#91a1b6;font-size:9px;margin-bottom:8px}.stat-label b{color:#eaf1ff;font-weight:500;margin-left:4px}.bar{height:4px;background:rgba(135,163,199,.16);border-radius:5px;overflow:hidden}.bar i{display:block;width:100%;height:100%;background:linear-gradient(90deg,#ff769a,#ffc0a1);box-shadow:0 0 10px #ff769a88;transition:width .24s}.xp-bar i{background:linear-gradient(90deg,#6fead5,#8ba8ff);box-shadow:0 0 10px #6fead588}.hud-center{text-align:center;padding-top:1px}.wave-label{font-size:10px;color:#8291a9}.wave-label b{color:var(--cyan);font-size:18px;margin-left:5px;vertical-align:-2px;font-weight:500}.wave-sub{display:block;font-size:8px;color:#506178;margin-top:8px}.hud-right{text-align:right}.score-label{font-size:8px;color:#8192a8}.score-number{font-size:25px;line-height:1.15;letter-spacing:.08em;font-weight:600;color:#f1f5ff;text-shadow:0 0 24px #8caaff44}.best-label{font-size:8px;color:#596980;margin-top:5px}.best-label span{color:#8b9ab0}.crosshair-hint{position:absolute;z-index:3;top:50%;right:clamp(24px,6vw,90px);color:#8294a8;font-size:8px;opacity:.65;pointer-events:none}.crosshair-hint span{font-size:15px;color:var(--cyan);vertical-align:-2px;margin-right:7px}.dash-status{position:absolute;z-index:3;bottom:75px;left:50%;transform:translateX(-50%);font-size:8px;color:#8694aa;display:flex;gap:7px;align-items:center;pointer-events:none}.dash-icon{font-size:16px;color:var(--cyan)}.dash-pips{display:flex;gap:3px;margin-left:4px}.dash-pips b{height:4px;width:13px;border-radius:3px;background:#74ead9;box-shadow:0 0 6px #74ead988}.dash-pips b.off{background:#354359;box-shadow:none}.toast{position:absolute;z-index:8;top:24%;left:50%;transform:translate(-50%,-10px);opacity:0;color:var(--cyan);font:10px var(--mono);letter-spacing:.15em;transition:.25s;pointer-events:none;text-shadow:0 0 14px #71f6e2}.toast.show{opacity:1;transform:translate(-50%,0)}.footer{position:absolute;z-index:4;bottom:0;left:0;right:0;height:42px;padding:0 clamp(18px,4.4vw,70px);border-top:1px solid rgba(151,183,224,.08);display:flex;align-items:center;justify-content:space-between;color:#526078;font-size:8px;pointer-events:none}.footer-center{color:#7a8a9e}.footer-center i{width:5px;height:5px}.overlay{position:absolute;z-index:6;inset:0;display:flex;align-items:center;justify-content:center;background:rgba(4,8,18,.62);backdrop-filter:blur(8px);opacity:0;visibility:hidden;transition:opacity .28s,visibility .28s}.overlay.visible{opacity:1;visibility:visible}.overlay-inner{text-align:center;width:min(94vw,610px);padding:40px 30px}.start-inner{padding-top:76px}.eyebrow{font-size:9px;color:#8da0b8;letter-spacing:.19em;display:flex;align-items:center;justify-content:center;gap:13px}.eyebrow-line{width:30px;height:1px;background:linear-gradient(90deg,transparent,#71f6e2)}.eyebrow-line:last-child{transform:rotate(180deg)}.hero-symbol{width:122px;height:106px;position:relative;margin:26px auto 17px;display:grid;place-items:center}.orbit{position:absolute;border:1px solid #65dfd244;border-radius:50%;width:112px;height:55px;transform:rotate(-30deg)}.orbit-b{width:112px;height:55px;transform:rotate(30deg);border-color:#86a8ff44}.core{font-size:25px;color:var(--cyan);text-shadow:0 0 28px #71f6e2;animation:pulse 2.8s ease-in-out infinite}@keyframes pulse{50%{transform:scale(1.14);filter:brightness(1.5)}}h1,h2{font-size:clamp(40px,7vw,68px);line-height:.91;letter-spacing:-.065em;margin:0;font-weight:600;color:#f1f5ff}h1 em,h2 em{font-style:normal;color:var(--cyan);text-shadow:0 0 35px #71f6e222}.intro-copy{font-size:14px;line-height:1.8;color:#93a1b6;margin:19px 0 22px}.intro-copy strong{font-weight:500;color:#dbe5f4}.primary-btn{min-width:190px;height:49px;position:relative;border:1px solid #71f6e2;background:linear-gradient(105deg,#7af4df,#b0ffe7);color:#08121b;font:700 11px var(--mono);letter-spacing:.16em;cursor:pointer;clip-path:polygon(0 0,calc(100% - 13px) 0,100% 13px,100% 100%,13px 100%,0 calc(100% - 13px));box-shadow:0 0 27px #71f6e21f;transition:transform .18s,filter .18s}.primary-btn:hover{transform:translateY(-2px);filter:brightness(1.12);box-shadow:0 0 32px #71f6e24c}.primary-btn b{font-size:16px;margin-left:15px;font-weight:400}.control-row{display:flex;justify-content:center;align-items:center;gap:17px;margin-top:30px;color:#8291a5;font-size:8px}.control-row span{display:flex;align-items:center;gap:3px}.control-row kbd{padding:4px 5px;border:1px solid #51617966;border-radius:3px;color:#c0ccdc;font:8px var(--mono);background:#10182a}.microcopy{margin-top:19px;color:#56667d;font-size:8px;letter-spacing:.17em}.mobile-tip{display:none;color:#71829a;font-size:8px;margin-top:16px}.compact-inner{width:min(92vw,470px);padding:42px 38px;background:linear-gradient(145deg,rgba(15,26,47,.9),rgba(7,13,26,.94));border:1px solid #8da6c326;box-shadow:0 25px 100px #0008;clip-path:polygon(0 0,calc(100% - 20px) 0,100% 20px,100% 100%,20px 100%,0 calc(100% - 20px))}.pause-glyph,.gameover-symbol{font-size:44px;color:var(--cyan);margin:18px 0 10px;text-shadow:0 0 30px #71f6e277}.gameover-symbol{color:var(--pink);font-size:64px;line-height:.8}.compact-inner h2{font-size:42px}.compact-inner h2 em{color:var(--pink);text-shadow:0 0 24px #ff729733}.compact-inner p{font-size:13px;color:#8392a8;margin:14px 0 23px}.text-btn{display:block;margin:20px auto 0;background:none;border:0;color:#7f8ea4;font:9px var(--mono);letter-spacing:.13em;cursor:pointer}.text-btn:hover{color:var(--cyan)}.level-inner{width:min(94vw,690px);padding-top:55px}.level-inner h2{font-size:clamp(37px,5vw,53px);margin-top:20px}.level-inner h2 em{color:#a7b5ff}.level-subtitle{color:#8492a8;font-size:13px;margin:12px 0 27px}.upgrade-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:12px}.upgrade-card{background:linear-gradient(145deg,#13213a,#0b1425);border:1px solid #91aad12a;padding:20px 16px 18px;text-align:left;color:var(--white);cursor:pointer;min-height:166px;position:relative;transition:.2s}.upgrade-card:hover{border-color:#71f6e2aa;transform:translateY(-4px);box-shadow:0 12px 28px #0005}.upgrade-card .upgrade-icon{font-size:22px;color:var(--cyan);margin-bottom:14px;display:block}.upgrade-card b{display:block;font:600 11px var(--mono);letter-spacing:.08em}.upgrade-card p{color:#8494aa;font-size:11px;line-height:1.5;margin:8px 0 0}.upgrade-card .card-num{position:absolute;right:12px;top:12px;color:#4e6079;font:8px var(--mono)}.run-stats{display:flex;justify-content:center;gap:34px;margin:25px 0 27px}.run-stats div{display:grid;gap:5px}.run-stats b{font:500 19px var(--mono);color:#f3f6ff}.run-stats span{font:8px var(--mono);color:#75849a;letter-spacing:.13em}.touch-controls{display:none}.joystick{position:absolute;left:24px;bottom:65px;width:118px;height:118px;z-index:5;touch-action:none}.joy-ring{position:absolute;inset:0;border-radius:50%;border:1px solid #a3bad034;background:#111b2c77;box-shadow:inset 0 0 25px #0003}.joy-knob{position:absolute;width:48px;height:48px;left:35px;top:35px;border-radius:50%;background:#9df6e622;border:1px solid #82ead975;box-shadow:0 0 18px #71f6e222;pointer-events:none}.touch-dash{position:absolute;right:25px;bottom:79px;width:64px;height:64px;border-radius:50%;z-index:5;background:#101a2bbd;color:var(--cyan);border:1px solid #71f6e277;font-size:24px;touch-action:none}.touch-dash small{display:block;font:7px var(--mono);letter-spacing:.1em;color:#9aabc0}.touch-controls{pointer-events:none}.touch-controls>*{pointer-events:auto}
@media(max-height:700px){.start-inner{padding-top:58px}.hero-symbol{margin:14px auto 10px;height:78px}.hero-symbol .orbit{width:90px;height:44px}.intro-copy{margin:12px 0 16px;font-size:12px}.control-row{margin-top:20px}.microcopy{margin-top:13px}.topbar{height:58px}.hud{top:72px}.footer{height:34px}}
@media(max-width:700px){.game-shell{min-height:460px}.topbar{height:58px;padding:0 16px}.brand{font-size:10px;gap:8px}.brand-mark{font-size:19px}.top-actions{gap:7px}.live-tag{font-size:7px;margin-right:2px}.icon-btn{width:30px;height:30px}.hud{left:16px;right:16px;top:72px;grid-template-columns:1fr 1fr 1fr}.hud-left{width:95%;}.stat-label{font-size:7px}.stat-card{margin-bottom:11px}.hud-center{padding-top:0}.wave-label{font-size:8px}.wave-label b{font-size:14px}.wave-sub{font-size:6px;max-width:90px;margin:6px auto}.score-label,.best-label{font-size:6px}.score-number{font-size:19px}.crosshair-hint{display:none}.dash-status{display:none}.footer{height:32px;padding:0 14px;font-size:6px}.footer-center{display:none}.start-inner{padding:62px 16px 40px}.eyebrow{font-size:7px;gap:8px}.eyebrow-line{width:18px}.hero-symbol{margin:15px auto 12px;width:90px;height:75px}.hero-symbol .orbit{width:88px;height:43px}.core{font-size:20px}h1{font-size:clamp(42px,12vw,60px)}.intro-copy{font-size:12px;margin:14px 0 18px}.primary-btn{height:45px;min-width:176px}.control-row{font-size:6px;gap:8px;margin-top:22px}.control-row kbd{font-size:7px;padding:3px}.microcopy{font-size:6px;margin-top:14px}.mobile-tip{display:block}.upgrade-grid{grid-template-columns:1fr;gap:8px}.level-inner{padding:50px 18px 35px;max-height:100dvh;overflow:auto}.level-inner h2{font-size:38px;margin-top:15px}.level-subtitle{margin:8px 0 16px;font-size:11px}.upgrade-card{min-height:0;padding:12px 14px 12px 52px}.upgrade-card .upgrade-icon{position:absolute;left:16px;top:16px;font-size:19px;margin:0}.upgrade-card b{font-size:9px}.upgrade-card p{font-size:9px;margin:4px 0 0}.upgrade-card .card-num{right:10px;top:9px}.level-inner .microcopy{margin-top:13px}.compact-inner{padding:32px 22px}.compact-inner h2{font-size:36px}.run-stats{gap:22px;margin:20px 0}.run-stats b{font-size:16px}.joystick{width:108px;height:108px;left:19px;bottom:48px}.joy-knob{left:31px;top:31px;width:46px;height:46px}.touch-dash{right:20px;bottom:62px;width:59px;height:59px}}
@media(pointer:coarse){.touch-controls{display:block}.control-row{display:none}.start-inner .microcopy{margin-top:22px}.mobile-tip{display:block}}

(() => {
  'use strict';
  const canvas = document.getElementById('game');
  const ctx = canvas.getContext('2d');
  const $ = id => document.getElementById(id);
  const ui = {
    start: $('startScreen'), pause: $('pauseScreen'), level: $('levelScreen'), over: $('gameOverScreen'),
    startBtn: $('startBtn'), resumeBtn: $('resumeBtn'), restartBtn: $('restartBtn'), restartPause: $('restartPauseBtn'),
    pauseBtn: $('pauseBtn'), soundBtn: $('soundBtn'), shell: $('gameShell'), health: $('healthBar'), healthText: $('healthText'),
    xp: $('xpBar'), xpText: $('xpText'), levelText: $('levelText'), wave: $('waveText'), waveSub: $('waveSub'),
    score: $('scoreText'), best: $('bestText'), dash: $('dashStatus'), dashPips: document.querySelector('.dash-pips'),
    toast: $('toast'), hint: $('aimHint'), joystick: $('joystick'), joyKnob: $('joyKnob'), touchDash: $('touchDash'),
    touchControls: $('touchControls'), upgradeGrid: $('upgradeGrid')
  };
  const TAU = Math.PI * 2;
  let W = 0, H = 0, dpr = 1, last = 0, time = 0;
  let state = 'menu', soundOn = false, audio = null, best = Number(localStorage.getItem('orbitalBest') || 0);
  let player, bullets = [], enemies = [], particles = [], pickups = [], stars = [], floaters = [];
  let score = 0, kills = 0, wave = 1, runTime = 0, spawnClock = 0, shotClock = 0, shake = 0, toastClock = 0;
  let keys = Object.create(null), mouse = { x: 0, y: 0, active: false, moved: false }, joy = { x: 0, y: 0, active: false, id: null };
  let pointerTouch = false, upgradesTaken = 0;
  const waveNames = ['THE OUTER RING','DARK MATTER DRIFT','THE SILENT BELT','ECHOES OF TITAN','EVENT HORIZON','THE LONG NIGHT'];
  const upgradePool = [
    { id:'rapid', icon:'⌁', name:'OVERCLOCKED COIL', detail:'Fire rate +22%', apply:p=>p.fireRate*=.78 },
    { id:'damage', icon:'✦', name:'PHOTON LANCE', detail:'Shot damage +1', apply:p=>p.damage+=1 },
    { id:'hull', icon:'◇', name:'REINFORCED HULL', detail:'Restore 35% hull', apply:p=>p.hp=Math.min(p.maxHp,p.hp+35) },
    { id:'speed', icon:'↗', name:'ION THRUSTERS', detail:'Movement speed +12%', apply:p=>p.speed*=1.12 },
    { id:'multishot', icon:'⌖', name:'SPLIT FOCUS', detail:'Fire an extra bolt', apply:p=>p.multishot=Math.min(3,p.multishot+1) },
    { id:'magnet', icon:'◎', name:'GRAVITY WELL', detail:'Collect shards from farther away', apply:p=>p.magnet+=55 },
    { id:'armor', icon:'⬡', name:'PHASE ARMOR', detail:'Take 15% less damage', apply:p=>p.armor=Math.min(.55,p.armor+.15) },
    { id:'dash', icon:'↯', name:'AFTERIMAGE', detail:'Dash cooldown -20%', apply:p=>p.dashCooldown*=.8 }
  ];
  const clamp = (v,a,b) => Math.max(a,Math.min(b,v));
  const rand = (a,b) => a + Math.random()*(b-a);
  const dist2 = (a,b) => (a.x-b.x)**2 + (a.y-b.y)**2;
  const fmt = n => String(Math.max(0,Math.floor(n))).padStart(6,'0');
  function resize(){
    const r = canvas.getBoundingClientRect(); W = r.width; H = r.height; dpr = Math.min(window.devicePixelRatio || 1, 2);
    canvas.width = Math.round(W*dpr); canvas.height = Math.round(H*dpr); ctx.setTransform(dpr,0,0,dpr,0,0);
    if(player){ player.x=clamp(player.x,40,W-40); player.y=clamp(player.y,90,H-45); }
    stars = Array.from({length:Math.floor(W*H/4700)},()=>({x:Math.random()*W,y:Math.random()*H,r:rand(.35,1.35),a:rand(.15,.65),p:rand(0,TAU),speed:rand(.3,1.3)}));
  }
  function newPlayer(){return {x:W/2,y:H/2,r:12,hp:100,maxHp:100,speed:225,fireRate:.2,damage:2,multishot:1,magnet:95,armor:0,dashCooldown:2.5,dashTimer:0,dashTime:0,invuln:0,angle:-Math.PI/2,trail:[],xp:0,level:1,nextXp:80,dead:false};}
  function reset(){
    player=newPlayer(); bullets=[];enemies=[];particles=[];pickups=[];floaters=[];score=0;kills=0;wave=1;runTime=0;spawnClock=.8;shotClock=0;shake=0;upgradesTaken=0;time=0;
    state='playing'; showOnly(null); ui.hint.style.opacity=mouse.moved?'0':'.65'; updateHud();
  }
  function showOnly(name){ [ui.start,ui.pause,ui.level,ui.over].forEach(el=>el.classList.remove('visible')); if(name)ui[name].classList.add('visible'); }
  function audioBeep(freq=440,duration=.08,type='sine',volume=.035){
    if(!soundOn)return; try{audio ||= new (window.AudioContext||window.webkitAudioContext)(); if(audio.state==='suspended')audio.resume();const o=audio.createOscillator(),g=audio.createGain();o.type=type;o.frequency.value=freq;g.gain.setValueAtTime(volume,audio.currentTime);g.gain.exponentialRampToValueAtTime(.001,audio.currentTime+duration);o.connect(g);g.connect(audio.destination);o.start();o.stop(audio.currentTime+duration);}catch(_){ }
  }
  function notify(text){ui.toast.textContent=text;ui.toast.classList.add('show');toastClock=1.6;}
  function setBest(){if(score>best){best=score;localStorage.setItem('orbitalBest',String(best));}}
  function updateHud(){
    if(!player)return; const health=clamp(player.hp/player.maxHp*100,0,100), xp=clamp(player.xp/player.nextXp*100,0,100);
    ui.health.style.width=health+'%';ui.healthText.textContent=Math.ceil(health)+'%';ui.health.style.background=health<30?'linear-gradient(90deg,#ff4e7e,#ffb08d)':'';
    ui.xp.style.width=xp+'%';ui.xpText.textContent=`${Math.floor(player.xp)} / ${player.nextXp}`;ui.levelText.textContent=String(player.level).padStart(2,'0');
    ui.wave.textContent=String(wave).padStart(2,'0');ui.waveSub.textContent=waveNames[Math.min(wave-1,waveNames.length-1)];ui.score.textContent=fmt(score);ui.best.textContent=fmt(best);
    const ready=player.dashTimer<=0;ui.dash.style.opacity=ready?'1':'.48'; const pips=ui.dashPips.children;for(let i=0;i<pips.length;i++)pips[i].classList.toggle('off',!ready);
  }
  function aimAt(x,y){mouse.x=x;mouse.y=y;mouse.active=true;mouse.moved=true;ui.hint.style.opacity='0';}
  function nearestEnemy(){let target=null,bestD=Infinity;for(const e of enemies){const d=dist2(player,e);if(d<bestD){bestD=d;target=e;}}return target;}
  function fire(){
    if(!player||shotClock>0)return;
    let angle=player.angle;
    if(mouse.active&&!pointerTouch){angle=Math.atan2(mouse.y-player.y,mouse.x-player.x);}
    else {const target=nearestEnemy();if(target)angle=Math.atan2(target.y-player.y,target.x-player.x);}
    player.angle=angle;
    const count=player.multishot, spread=count===1?0:.18;
    for(let i=0;i<count;i++){
      const a=angle+(i-(count-1)/2)*spread;
      bullets.push({x:player.x+Math.cos(a)*15,y:player.y+Math.sin(a)*15,vx:Math.cos(a)*610,vy:Math.sin(a)*610,r:3.2,life:1.05,damage:player.damage});
    }
    shotClock=player.fireRate; audioBeep(520,.045,'triangle',.014);
    for(let i=0;i<2;i++)particles.push({x:player.x+Math.cos(angle)*15,y:player.y+Math.sin(angle)*15,vx:rand(-20,20)+Math.cos(angle)*rand(20,65),vy:rand(-20,20)+Math.sin(angle)*rand(20,65),life:.16,max:.16,size:rand(1,2.4),color:'#a9fff1'});
  }
  function spawnEnemy(){
    const pad=40, side=Math.floor(Math.random()*4);let x,y;
    if(side===0){x=rand(0,W);y=-pad;}else if(side===1){x=W+pad;y=rand(70,H);}else if(side===2){x=rand(0,W);y=H+pad;}else{x=-pad;y=rand(70,H);}
    const t=runTime, roll=Math.random();let type='drifter';if(wave>=2&&roll<.3)type='skitter';if(wave>=3&&roll<.16)type='brute';if(wave>=4&&roll<.28)type='wisp';
    const spec={drifter:{r:11,hp:3,speed:63+wave*4,color:'#ff6688',damage:12,score:10},skitter:{r:8,hp:2,speed:112+wave*5,color:'#ffad72',damage:9,score:14},brute:{r:17,hp:8+Math.floor(wave/2),speed:40+wave*2,color:'#bb85ff',damage:22,score:28},wisp:{r:10,hp:4,speed:58+wave*3,color:'#68adff',damage:10,score:18}}[type];
    enemies.push({x,y,type,...spec,maxHp:spec.hp,attackClock:rand(0,1.4),phase:rand(0,TAU),hit:0});
  }
  function spawnPickup(x,y,kind='xp',value=1){pickups.push({x,y,vx:rand(-35,35),vy:rand(-35,35),kind,value,r:kind==='heal'?7:5,life:12,phase:rand(0,TAU)});}
  function burst(x,y,color,n=8,power=100){for(let i=0;i<n;i++){const a=rand(0,TAU),s=rand(power*.25,power);particles.push({x,y,vx:Math.cos(a)*s,vy:Math.sin(a)*s,life:rand(.22,.55),max:.55,size:rand(1.2,3.8),color});}}
  function damagePlayer(amount){if(player.invuln>0||player.dashTime>0)return;player.hp-=amount*(1-player.armor);player.invuln=.7;shake=8;burst(player.x,player.y,'#ff7799',12,120);audioBeep(120,.18,'sawtooth',.045);if(player.hp<=0){player.hp=0;finish();}updateHud();}
  function killEnemy(index){const e=enemies[index];enemies.splice(index,1);kills++;score+=e.score;setBest();burst(e.x,e.y,e.color,e.type==='brute'?18:10,e.type==='brute'?145:105);spawnPickup(e.x,e.y,'xp',e.type==='brute'?16:8);if(Math.random()<.095)spawnPickup(e.x+rand(-12,12),e.y+rand(-12,12),'heal');if(kills%12===0)notify('THREAT LEVEL RISING');audioBeep(190,.08,'sine',.018);}
  function gainXp(value){player.xp+=value;if(player.xp>=player.nextXp){player.xp-=player.nextXp;player.level++;player.nextXp=Math.floor(player.nextXp*1.3+18);levelUp();}}
  function levelUp(){state='level';ui.newLevelText.textContent=String(player.level).padStart(2,'0');const choices=[...upgradePool].sort(()=>Math.random()-.5).slice(0,3);ui.upgradeGrid.innerHTML='';choices.forEach((u,i)=>{const b=document.createElement('button');b.className='upgrade-card';b.innerHTML=`<span class="card-num">0${i+1}</span><span class="upgrade-icon">${u.icon}</span><b>${u.name}</b><p>${u.detail}</p>`;b.addEventListener('click',()=>{u.apply(player);upgradesTaken++;state='playing';showOnly(null);burst(player.x,player.y,'#81f5df',17,110);notify('PROTOCOL INSTALLED');audioBeep(740,.12,'sine',.035);updateHud();});ui.upgradeGrid.appendChild(b);});showOnly('level');audioBeep(620,.12,'sine',.025);}
  function finish(){state='over';player.dead=true;showOnly('over');$('finalScore').textContent=fmt(score);$('finalWave').textContent=String(wave).padStart(2,'0');$('finalKills').textContent=String(kills).padStart(2,'0');$('finalMessage').textContent=runTime>100?'You kept the signal alive longer than most.':'The dark found you. The signal remembers.';setBest();updateHud();}
  function dash(){if(state!=='playing'||player.dashTimer>0)return;let dx=(keys.d||keys.arrowright?1:0)-(keys.a||keys.arrowleft?1:0)+joy.x,dy=(keys.s||keys.arrowdown?1:0)-(keys.w||keys.arrowup?1:0)+joy.y;let m=Math.hypot(dx,dy);if(m<.1){dx=Math.cos(player.angle);dy=Math.sin(player.angle);m=1;}player.vx=dx/m*590;player.vy=dy/m*590;player.dashTimer=player.dashCooldown;player.dashTime=.2;player.invuln=.3;burst(player.x,player.y,'#71f6e2',8,65);audioBeep(260,.16,'sawtooth',.025);updateHud();}

