function update(dt){
  time+=dt;if(toastClock>0){toastClock-=dt;if(toastClock<=0)ui.toast.classList.remove('show');}
  for(const s of stars)s.p+=dt*s.speed;
  particles=particles.filter(p=>p.life>0);for(const p of particles){p.life-=dt;p.x+=p.vx*dt;p.y+=p.vy*dt;p.vx*=Math.pow(.08,dt);p.vy*=Math.pow(.08,dt);}
  if(state!=='playing'||!player)return;
  runTime+=dt;const nextWave=1+Math.floor(runTime/24);if(nextWave!==wave){wave=nextWave;notify(`SECTOR ${String(wave).padStart(2,'0')} — HOSTILES INBOUND`);burst(W/2,115,'#71f6e2',18,130);}
  const spawnRate=Math.max(.34,1.35-wave*.075);spawnClock-=dt;if(spawnClock<=0){spawnEnemy();if(wave>=4&&Math.random()<.14)spawnEnemy();spawnClock=spawnRate*rand(.7,1.25);}
  shotClock-=dt;player.dashTimer=Math.max(0,player.dashTimer-dt);player.dashTime=Math.max(0,player.dashTime-dt);player.invuln=Math.max(0,player.invuln-dt);
  let dx=(keys.d||keys.arrowright?1:0)-(keys.a||keys.arrowleft?1:0)+joy.x,dy=(keys.s||keys.arrowdown?1:0)-(keys.w||keys.arrowup?1:0)+joy.y;const mag=Math.hypot(dx,dy);if(mag>1){dx/=mag;dy/=mag;}
  if(player.dashTime>0){player.x+=player.vx*dt;player.y+=player.vy*dt;player.trail.push({x:player.x,y:player.y,a:.5});}
  else{player.x+=dx*player.speed*dt;player.y+=dy*player.speed*dt;player.angle=mouse.active&&!pointerTouch?Math.atan2(mouse.y-player.y,mouse.x-player.x):player.angle;}
  player.x=clamp(player.x,27,W-27);player.y=clamp(player.y,78,H-42);player.trail=player.trail.filter(t=>t.a>.02);for(const t of player.trail)t.a-=dt*1.6;
  fire();
  for(const e of enemies){
    e.phase+=dt*2;e.hit=Math.max(0,e.hit-dt);const a=Math.atan2(player.y-e.y,player.x-e.x),d=Math.hypot(player.x-e.x,player.y-e.y);
    if(e.type==='wisp'){
      e.x+=Math.cos(a+Math.sin(e.phase)*.9)*e.speed*dt;e.y+=Math.sin(a+Math.sin(e.phase)*.9)*e.speed*dt;e.attackClock-=dt;
      if(e.attackClock<=0&&d<490){hostile.push({x:e.x,y:e.y,vx:Math.cos(a)*170,vy:Math.sin(a)*170,r:4,life:3});e.attackClock=2.2;}
    }else{e.x+=Math.cos(a)*e.speed*dt;e.y+=Math.sin(a)*e.speed*dt;}
    if(d<e.r+player.r-2)damagePlayer(e.damage*dt*1.8);
  }
  for(const b of bullets){b.x+=b.vx*dt;b.y+=b.vy*dt;b.life-=dt;for(let i=enemies.length-1;i>=0;i--){const e=enemies[i];if(dist2(b,e)<(b.r+e.r)**2){e.hp-=b.damage;e.hit=.12;b.life=0;burst(b.x,b.y,e.color,3,42);if(e.hp<=0)killEnemy(i);break;}}}
  bullets=bullets.filter(b=>b.life>0&&b.x>-30&&b.x<W+30&&b.y>-30&&b.y<H+30);
  for(const b of hostile){b.x+=b.vx*dt;b.y+=b.vy*dt;b.life-=dt;if(dist2(b,player)<(b.r+player.r)**2){b.life=0;damagePlayer(8);burst(b.x,b.y,'#78aaff',5,70);}}
  hostile=hostile.filter(b=>b.life>0);
  for(const p of pickups){p.life-=dt;p.phase+=dt*4;const d=Math.hypot(player.x-p.x,player.y-p.y);if(d<player.magnet){const pull=1-d/player.magnet;p.vx+=(player.x-p.x)*pull*dt*5;p.vy+=(player.y-p.y)*pull*dt*5;}p.x+=p.vx*dt;p.y+=p.vy*dt;p.vx*=Math.pow(.4,dt);p.vy*=Math.pow(.4,dt);if(d<player.r+p.r+4){p.life=0;if(p.kind==='heal'){player.hp=Math.min(player.maxHp,player.hp+22);notify('HULL RESTORED +22');audioBeep(700,.12,'sine',.025);}else{score+=p.value;gainXp(p.value);audioBeep(790,.035,'sine',.012);}setBest();}}
  pickups=pickups.filter(p=>p.life>0);
  shake=Math.max(0,shake-dt*24);updateHud();
}
function glow(color,blur){ctx.shadowColor=color;ctx.shadowBlur=blur;}
function polygon(x,y,r,sides,rot=0){ctx.beginPath();for(let i=0;i<sides;i++){const a=rot+i*TAU/sides;const px=x+Math.cos(a)*r,py=y+Math.sin(a)*r;if(i===0)ctx.moveTo(px,py);else ctx.lineTo(px,py);}ctx.closePath();}
function render(){
  ctx.clearRect(0,0,W,H);const sx=shake?rand(-shake,shake):0,sy=shake?rand(-shake,shake):0;ctx.save();ctx.translate(sx,sy);
  const bg=ctx.createRadialGradient(W*.5,H*.48,20,W*.5,H*.48,Math.max(W,H)*.72);bg.addColorStop(0,'#101a30');bg.addColorStop(.58,'#0a1121');bg.addColorStop(1,'#070a14');ctx.fillStyle=bg;ctx.fillRect(0,0,W,H);
  // Quiet starfield and coordinate lattice
  for(const s of stars){ctx.globalAlpha=s.a*(.72+.28*Math.sin(s.p));ctx.fillStyle='#b9d1ef';ctx.fillRect(s.x,s.y,s.r,s.r);}ctx.globalAlpha=1;
  ctx.strokeStyle='rgba(113,169,221,.035)';ctx.lineWidth=1;const grid=64,offset=(time*2)%grid;for(let x=0;x<W;x+=grid){ctx.beginPath();ctx.moveTo(x,65);ctx.lineTo(x,H-35);ctx.stroke();}for(let y=offset+65;y<H-35;y+=grid){ctx.beginPath();ctx.moveTo(0,y);ctx.lineTo(W,y);ctx.stroke();}
  const rad=Math.min(W,H)*.34;ctx.strokeStyle='rgba(102,206,215,.075)';ctx.setLineDash([2,10]);ctx.beginPath();ctx.arc(W/2,H/2,rad,0,TAU);ctx.stroke();ctx.setLineDash([]);
  // Corner registration marks
  ctx.strokeStyle='rgba(113,246,226,.27)';ctx.lineWidth=1;const corners=[[28,85,1,1],[W-28,85,-1,1],[28,H-42,1,-1],[W-28,H-42,-1,-1]];for(const [x,y,dx0,dy0] of corners){ctx.beginPath();ctx.moveTo(x,y+dy0*13);ctx.lineTo(x,y);ctx.lineTo(x+dx0*13,y);ctx.stroke();}
  for(const p of particles){ctx.globalAlpha=clamp(p.life/p.max,0,1);ctx.fillStyle=p.color;glow(p.color,9);ctx.beginPath();ctx.arc(p.x,p.y,p.size,0,TAU);ctx.fill();ctx.shadowBlur=0;}ctx.globalAlpha=1;
  for(const p of pickups){const pulse=1+Math.sin(p.phase)*.13;ctx.save();ctx.translate(p.x,p.y);ctx.rotate(p.phase*.25);ctx.fillStyle=p.kind==='heal'?'#ff8baf':'#72f4df';glow(ctx.fillStyle,14);polygon(0,0,p.r*pulse,4,Math.PI/4);ctx.fill();ctx.shadowBlur=0;ctx.strokeStyle='rgba(235,255,255,.7)';ctx.lineWidth=1;ctx.stroke();ctx.restore();}
  for(const b of bullets){ctx.fillStyle='#adfff4';glow('#71f6e2',13);ctx.beginPath();ctx.arc(b.x,b.y,b.r,0,TAU);ctx.fill();ctx.shadowBlur=0;}
  for(const b of hostile){ctx.fillStyle='#81baff';glow('#6ba9ff',12);ctx.beginPath();ctx.arc(b.x,b.y,b.r,0,TAU);ctx.fill();ctx.shadowBlur=0;}
  for(const e of enemies){ctx.save();ctx.translate(e.x,e.y);ctx.rotate(e.phase*.16);const col=e.hit?'#fff':e.color;glow(col,e.type==='brute'?22:15);ctx.fillStyle=col+'22';ctx.strokeStyle=col;ctx.lineWidth=e.type==='brute'?2:1.5;
    if(e.type==='brute'){polygon(0,0,e.r,6,Math.PI/6);ctx.fill();ctx.stroke();polygon(0,0,e.r*.53,6,0);ctx.stroke();}
    else if(e.type==='skitter'){polygon(0,0,e.r,4,Math.PI/4);ctx.fill();ctx.stroke();ctx.beginPath();ctx.moveTo(-e.r-4,0);ctx.lineTo(-e.r*.35,0);ctx.moveTo(e.r*.35,0);ctx.lineTo(e.r+4,0);ctx.stroke();}
    else if(e.type==='wisp'){ctx.beginPath();ctx.arc(0,0,e.r,0,TAU);ctx.fill();ctx.stroke();ctx.beginPath();ctx.arc(0,0,e.r*.52,0,TAU);ctx.stroke();}
    else{polygon(0,0,e.r,6,Math.PI/6);ctx.fill();ctx.stroke();ctx.beginPath();ctx.arc(0,0,e.r*.38,0,TAU);ctx.stroke();}
    ctx.shadowBlur=0;ctx.fillStyle='#ffe2e9';ctx.beginPath();ctx.arc(0,0,2,0,TAU);ctx.fill();if(e.hp<e.maxHp){ctx.fillStyle='#ffffff2a';ctx.fillRect(-e.r,-e.r-7,e.r*2,2);ctx.fillStyle=e.color;ctx.fillRect(-e.r,-e.r-7,e.r*2*clamp(e.hp/e.maxHp,0,1),2);}ctx.restore();}
  if(player){
    for(const t of player.trail){ctx.globalAlpha=t.a;ctx.fillStyle='#71f6e2';glow('#71f6e2',14);polygon(t.x,t.y,10,3,player.angle);ctx.fill();ctx.shadowBlur=0;}ctx.globalAlpha=1;
    const flicker=player.invuln>0&&Math.floor(time*18)%2===0; if(!flicker){ctx.save();ctx.translate(player.x,player.y);ctx.rotate(player.angle+Math.PI/2);glow('#71f6e2',player.dashTime>0?30:19);ctx.fillStyle='#c9fff6';ctx.strokeStyle='#71f6e2';ctx.lineWidth=1.5;ctx.beginPath();ctx.moveTo(0,-15);ctx.lineTo(10,11);ctx.lineTo(0,7);ctx.lineTo(-10,11);ctx.closePath();ctx.fill();ctx.stroke();ctx.shadowBlur=0;ctx.fillStyle='#183b48';ctx.beginPath();ctx.arc(0,-1,3.2,0,TAU);ctx.fill();if(Math.hypot(dx,dy)>.1||player.dashTime>0){ctx.fillStyle='#ffcb8b';glow('#ffb976',10);ctx.beginPath();ctx.moveTo(-3,10);ctx.lineTo(0,rand(14,20));ctx.lineTo(3,10);ctx.fill();ctx.shadowBlur=0;}ctx.restore();}
    const halo=ctx.createRadialGradient(player.x,player.y,2,player.x,player.y,37);halo.addColorStop(0,'rgba(95,245,219,.1)');halo.addColorStop(1,'rgba(95,245,219,0)');ctx.fillStyle=halo;ctx.beginPath();ctx.arc(player.x,player.y,37,0,TAU);ctx.fill();
  }
  // Tiny idle particles give the arena a breathing signal.
  if(state==='menu'&&Math.random()<.16)particles.push({x:rand(0,W),y:rand(80,H-40),vx:rand(-5,5),vy:rand(-15,-4),life:2,max:2,size:rand(.8,2),color:'#76f5df'});
  ctx.restore();
}
function frame(now){const dt=Math.min(.033,(now-last)/1000||0);last=now;update(dt);render();requestAnimationFrame(frame);}

