(() => {
'use strict';
const canvas=document.getElementById('game'),ctx=canvas.getContext('2d'),$=id=>document.getElementById(id);
const ui={start:$('startScreen'),pause:$('pauseScreen'),level:$('levelScreen'),over:$('gameOverScreen'),startBtn:$('startBtn'),resumeBtn:$('resumeBtn'),restartBtn:$('restartBtn'),restartPause:$('restartPauseBtn'),pauseBtn:$('pauseBtn'),soundBtn:$('soundBtn'),health:$('healthBar'),healthText:$('healthText'),xp:$('xpBar'),xpText:$('xpText'),levelText:$('levelText'),wave:$('waveText'),waveSub:$('waveSub'),score:$('scoreText'),best:$('bestText'),dash:$('dashStatus'),dashPips:document.querySelector('.dash-pips'),toast:$('toast'),hint:$('aimHint'),joystick:$('joystick'),joyKnob:$('joyKnob'),touchDash:$('touchDash'),upgradeGrid:$('upgradeGrid')};
const TAU=Math.PI*2,clamp=(v,a,b)=>Math.max(a,Math.min(b,v)),rand=(a,b)=>a+Math.random()*(b-a),dist2=(a,b)=>(a.x-b.x)**2+(a.y-b.y)**2,fmt=n=>String(Math.max(0,Math.floor(n))).padStart(6,'0');
