let player,bullets=[],hostile=[],enemies=[],particles=[],pickups=[],stars=[],score=0,kills=0,wave=1,runTime=0,spawnClock=0,shotClock=0,shake=0,toastClock=0;
let keys=Object.create(null),mouse={x:0,y:0,active:false,moved:false},joy={x:0,y:0,active:false,id:null},pointerTouch=false;
const waveNames=['THE OUTER RING','DARK MATTER DRIFT','THE SILENT BELT','ECHOES OF TITAN','EVENT HORIZON','THE LONG NIGHT'];
const upgradePool=[
{id:'rapid',icon:'⌁',name:'OVERCLOCKED COIL',detail:'Fire rate +22%',apply:p=>p.fireRate*=.78},
{id:'damage',icon:'✦',name:'PHOTON LANCE',detail:'Shot damage +1',apply:p=>p.damage++},
{id:'hull',icon:'◇',name:'REINFORCED HULL',detail:'Restore 35% hull',apply:p=>p.hp=Math.min(p.maxHp,p.hp+35)},
{id:'speed',icon:'↗',name:'ION THRUSTERS',detail:'Movement speed +12%',apply:p=>p.speed*=1.12},
{id:'multishot',icon:'⌖',name:'SPLIT FOCUS',detail:'Fire an extra bolt',apply:p=>p.multishot=Math.min(3,p.multishot+1)},
{id:'magnet',icon:'◎',name:'GRAVITY WELL',detail:'Collect shards from farther away',apply:p=>p.magnet+=55},
{id:'armor',icon:'⬡',name:'PHASE ARMOR',detail:'Take 15% less damage',apply:p=>p.armor=Math.min(.55,p.armor+.15)},
{id:'dash',icon:'↯',name:'AFTERIMAGE',detail:'Dash cooldown -20%',apply:p=>p.dashCooldown*=.8}];
function resize(){const r=canvas.getBoundingClientRect();W=r.width;H=r.height;dpr=Math.min(devicePixelRatio||1,2);canvas.width=Math.round(W*dpr);canvas.height=Math.round(H*dpr);ctx.setTransform(dpr,0,0,dpr,0,0);if(player){player.x=clamp(player.x,40,W-40);player.y=clamp(player.y,90,H-45);}stars=Array.from({length:Math.floor(W*H/4700)},()=>({x:Math.random()*W,y:Math.random()*H,r:rand(.35,1.35),a:rand(.15,.65),p:rand(0,TAU),speed:rand(.3,1.3)}));}
function newPlayer(){return{x:W/2,y:H/2,r:12,hp:100,maxHp:100,speed:225,fireRate:.2,damage:2,multishot:1,magnet:95,armor:0,dashCooldown:2.5,dashTimer:0,dashTime:0,invuln:0,angle:-Math.PI/2,trail:[],xp:0,level:1,nextXp:80,vx:0,vy:0};}
function showOnly(name){[ui.start,ui.pause,ui.level,ui.over].forEach(el=>el.classList.remove('visible'));if(name)ui[name].classList.add('visible');}
function reset(){player=newPlayer();bullets=[];hostile=[];enemies=[];particles=[];pickups=[];score=0;kills=0;wave=1;runTime=0;spawnClock=.8;shotClock=0;shake=0;time=0;state='playing';showOnly(null);ui.hint.style.opacity=mouse.moved?'0':'.65';updateHud();}
function beep(freq=440,duration=.08,type='sine',volume=.035){if(!soundOn)return;try{audio||=new(window.AudioContext||window.webkitAudioContext)();if(audio.state==='suspended')audio.resume();const o=audio.createOscillator(),g=audio.createGain();o.type=type;o.frequency.value=freq;g.gain.setValueAtTime(volume,audio.currentTime);g.gain.exponentialRampToValueAtTime(.001,audio.currentTime+duration);o.connect(g);g.connect(audio.destination);o.start();o.stop(audio.currentTime+duration);}catch(_){}}
function notify(text){ui.toast.textContent=text;ui.toast.classList.add('show');toastClock=1.6;}
function setBest(){if(score>best){best=score;localStorage.setItem('orbitalBest',String(best));}}
