function frame(now){const dt=Math.min(.033,(now-last)/1000||0);last=now;update(dt);render();requestAnimationFrame(frame);}
function togglePause(){if(state==='playing'){state='paused';showOnly('pause');}else if(state==='paused'){state='playing';showOnly(null);last=performance.now();}}
function aimAt(x,y){mouse.x=x;mouse.y=y;mouse.active=true;mouse.moved=true;ui.hint.style.opacity='0';}
function joyMove(e){const r=ui.joystick.getBoundingClientRect(),cx=r.left+r.width/2,cy=r.top+r.height/2;let x=e.clientX-cx,y=e.clientY-cy;const max=37,m=Math.hypot(x,y);if(m>max){x=x/m*max;y=y/m*max;}joy.x=x/max;joy.y=y/max;ui.joyKnob.style.transform=`translate(${x}px,${y}px)`;}
ui.startBtn.addEventListener('click',()=>{reset();beep(480,.12,'triangle',.03);});
ui.restartBtn.addEventListener('click',()=>{reset();beep(480,.12,'triangle',.03);});
ui.restartPause.addEventListener('click',reset);
ui.resumeBtn.addEventListener('click',togglePause);
ui.pauseBtn.addEventListener('click',togglePause);
ui.soundBtn.addEventListener('click',()=>{soundOn=!soundOn;ui.soundBtn.textContent=soundOn?'♫':'♪';ui.soundBtn.style.color=soundOn?'#71f6e2':'';if(soundOn)beep(660,.1);});
window.addEventListener('keydown',e=>{const k=e.key.toLowerCase();if([' ','arrowup','arrowdown','arrowleft','arrowright'].includes(k))e.preventDefault();keys[k]=true;if(k===' '&&!e.repeat)dash();if((k==='p'||k==='escape')&&(state==='playing'||state==='paused'))togglePause();});
window.addEventListener('keyup',e=>{keys[e.key.toLowerCase()]=false;});window.addEventListener('blur',()=>{keys=Object.create(null);if(state==='playing')togglePause();});
canvas.addEventListener('pointermove',e=>{if(e.pointerType==='mouse'){pointerTouch=false;aimAt(e.clientX,e.clientY);}else if(e.pointerType==='touch'&&e.buttons){pointerTouch=true;aimAt(e.clientX,e.clientY);}});
canvas.addEventListener('pointerdown',e=>{if(e.pointerType==='mouse'){pointerTouch=false;aimAt(e.clientX,e.clientY);}else{pointerTouch=true;aimAt(e.clientX,e.clientY);}});
ui.joystick.addEventListener('pointerdown',e=>{e.preventDefault();joy.active=true;joy.id=e.pointerId;ui.joystick.setPointerCapture(e.pointerId);joyMove(e);});
ui.joystick.addEventListener('pointermove',e=>{if(joy.active&&e.pointerId===joy.id)joyMove(e);});
const joyEnd=e=>{if(e.pointerId===joy.id){joy.active=false;joy.x=joy.y=0;joy.id=null;ui.joyKnob.style.transform='translate(0,0)';}};
ui.joystick.addEventListener('pointerup',joyEnd);ui.joystick.addEventListener('pointercancel',joyEnd);
ui.touchDash.addEventListener('pointerdown',e=>{e.preventDefault();dash();});
window.addEventListener('resize',resize);resize();ui.best.textContent=fmt(best);requestAnimationFrame(frame);
})();

